import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../styles/Dashboard.css';

const Dashboard = () => {
  const [stats, setStats] = useState({ devis: 0, factures: 0, montant: 0 });
  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const token = localStorage.getItem('token');

  useEffect(() => {
    if (token) {
      fetchStats();
    }
  }, []);

  const fetchStats = async () => {
    try {
      const config = { headers: { Authorization: `Bearer ${token}` } };
      const devisRes = await axios.get('http://localhost:8000/api/devis', config);
      const facturesRes = await axios.get('http://localhost:8000/api/factures', config);
      setStats({
        devis: devisRes.data.data?.length || 0,
        factures: facturesRes.data.data?.length || 0,
        montant: facturesRes.data.data?.reduce((sum, f) => sum + parseFloat(f.montant_restant || 0), 0) || 0
      });
    } catch (err) {
      console.error('Erreur:', err);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    window.location.href = '/login';
  };

  return (
    <div style={{ minHeight: '100vh', background: '#f5f7fb', padding: '20px' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
          <div>
            <h1 style={{ margin: 0, color: '#333' }}>Tableau de bord</h1>
            <p style={{ margin: '5px 0 0 0', color: '#666' }}>Bienvenue, {user.prenom} {user.nom} 👋</p>
          </div>
          <button onClick={handleLogout} style={{ padding: '10px 20px', background: '#f44336', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
            Déconnexion
          </button>
        </div>

        {/* Stats Cards */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginBottom: '30px' }}>
          <div style={{ background: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              <div style={{ width: '50px', height: '50px', background: '#e3f2fd', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px' }}>📄</div>
              <div>
                <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>MES DEVIS</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '28px', fontWeight: 'bold' }}>{stats.devis}</p>
              </div>
            </div>
          </div>

          <div style={{ background: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              <div style={{ width: '50px', height: '50px', background: '#e8f5e9', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px' }}>🧾</div>
              <div>
                <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>MES FACTURES</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '28px', fontWeight: 'bold' }}>{stats.factures}</p>
              </div>
            </div>
          </div>

          <div style={{ background: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              <div style={{ width: '50px', height: '50px', background: '#fff3e0', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px' }}>💶</div>
              <div>
                <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>MONTANT DÛ</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '28px', fontWeight: 'bold' }}>{stats.montant.toFixed(2)} €</p>
              </div>
            </div>
          </div>
        </div>

        {/* Actions rapides */}
        <div style={{ background: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
          <h2 style={{ margin: '0 0 20px 0', display: 'flex', alignItems: 'center', gap: '10px' }}>📁 Actions rapides</h2>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '15px' }}>
            <a href="/devis" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', background: '#f5f7fb', borderRadius: '10px', textDecoration: 'none', color: '#333', transition: 'background 0.2s' }}>
              <span style={{ fontSize: '24px' }}>📄</span>
              <span style={{ fontWeight: '500' }}>Voir mes devis</span>
            </a>

            <a href="/factures" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', background: '#f5f7fb', borderRadius: '10px', textDecoration: 'none', color: '#333', transition: 'background 0.2s' }}>
              <span style={{ fontSize: '24px' }}>🧾</span>
              <span style={{ fontWeight: '500' }}>Consulter mes factures</span>
            </a>

            <a href="/produits" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', background: '#e8f5e9', borderRadius: '10px', textDecoration: 'none', color: '#333', transition: 'background 0.2s', border: '2px solid #4caf50' }}>
              <span style={{ fontSize: '24px' }}>🛒</span>
              <span style={{ fontWeight: '500' }}>Nos Produits</span>
            </a>

            <a href="/devis" style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', background: '#e3f2fd', borderRadius: '10px', textDecoration: 'none', color: '#333', transition: 'background 0.2s', border: '2px solid #2196f3' }}>
              <span style={{ fontSize: '24px' }}>➕</span>
              <span style={{ fontWeight: '500' }}>Créer un devis</span>
            </a>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
